router.post( '/likePost/:id', protect, async( req, res ) => {
    const userId = req.user.id;
    const postId = req.params.id;

    const postExists = await Post.findById(postId);

    if(!postExists){
        return res.status(404).json({ message: 'Post does not exist' });
    }

    try{
        await Post.findByIdAndUpdate(postId, { $addToSet: { likes: userId } }, {new: true});
        await User.findByIdAndUpdate(userId, { $addToSet: { postLikes: postId } }, {new: true})
        res.status(201).json({ message: 'Post Liked!' });
    }catch(err){
        res.status(500).json({ message: err.message });
    }
} )

router.post( '/unlikePost/:id', protect, async( req, res ) => {
    const userId = req.user.id;
    const postId = req.params.id;
    const postExists = await Post.findById(postId);

    if(!postExists){
        return res.status(404).json({ message: 'Post does not exist' });
    }

    try{
        await Post.findByIdAndUpdate(postId, { $pull: { likes: userId } }, {new: true});
        await User.findByIdAndUpdate(userId, { $pull: { postLikes: postId } }, {new: true})
        res.status(200).json({ message: 'Post Unliked!' });
    }catch(err){
        res.status(500).json({ message: err.message });
    }
} )

