exports.createPost = async (req, res) => {

    if (!req.body.content) {
        return res.status(400).json({ message: 'No Content Provided in Post.' })
    }

    const post = new Post({
        content: req.body.content,
        creator: req.user.id,
    });

    try {
        const newPost = await post.save();
        await User.findByIdAndUpdate(req.user.id, { $addToSet: { posts: newPost._id } }, { new: true })
        res.json(newPost);
    } catch (err) {
        res.json({ message: err.message });
    }
}

